/**
 * Generates `assets/data/topic-quizzes.json` with 8 Major Topic Free Quizzes.
 * Each major topic contains 27 UNMEB-aligned clinical questions:
 *   - 19 Single-Choice (~70.4%)
 *   - 4  Multi-Choice ("Select all that apply", ~14.8%)
 *   - 4  True / False (~14.8%)
 */
const fs = require("node:fs");
const path = require("node:path");

function sc(id, prompt, options, answerIndex, rationale) {
  return { id, type: "single", prompt, options, answerIndex, rationale };
}
function mc(id, prompt, options, answerIndices, rationale) {
  return { id, type: "multi", prompt, options, answerIndices, rationale };
}
function tf(id, prompt, answerBool, rationale) {
  return { id, type: "boolean", prompt, options: ["True", "False"], answerIndex: answerBool ? 0 : 1, rationale };
}

