    questions: [
      sc("pd-1", "According to Uganda IMCI guidelines, which finding is an immediate General Danger Sign requiring urgent Pink hospital referral?", ["Mild runny nose for 2 days", "Convulsions, lethargy/unconsciousness, vomiting everything, or unable to drink/breastfeed", "Isolated mild diaper rash", "Teething irritability"], 1, "Any General Danger Sign classifies as Severe Disease (Pink) requiring pre-referral care and urgent transfer."),
      sc("pd-2", "Under the UNEPI (Uganda National Expanded Programme on Immunization) schedule, which vaccines are given at BIRTH?", ["Measles and Yellow Fever", "BCG (right upper arm ID) and OPV 0", "Pentavalent 1 and PCV 1", "HPV only"], 1, "At birth: BCG intradermally + OPV 0 oral."),
      sc("pd-3", "Which MUAC (Mid-Upper Arm Circumference) measurement in a 2-year-old child indicates Severe Acute Malnutrition (SAM)?", ["< 11.5 cm (Red)", "12.5 – 13.4 cm (Yellow)", "> 13.5 cm (Green)", "15.0 cm"], 0, "MUAC < 11.5 cm (or bilateral pitting oedema) defines Severe Acute Malnutrition."),
      sc("pd-4", "What is the key nutritional hallmark distinguishing Kwashiorkor from Marasmus?", ["Marked bilateral pitting edema, hepatomegaly, flaky-paint dermatitis & 'moon face'", "Extreme severe muscle/fat wasting ('skin and bones') with alert hungry appearance", "Normal serum albumin", "Tall stature"], 0, "Kwashiorkor is protein-deficiency oedematous malnutrition; Marasmus is total calorie wasting."),
      sc("pd-5", "In Uganda Clinical Guidelines, what is the first-line management for a child with Moderate (Some) Dehydration from acute diarrhea?", ["Immediate IV Ceftriaxone alone", "Low-osmolarity ORS (75 mL/kg over 4 hours) + Zinc supplementation (10–20 mg/day for 10–14 days)", "Withhold all breastmilk", "Loperamide anti-motility syrup"], 1, "Never give antimotility drugs in children; give ORS + Zinc 20 mg/day (10 mg if < 6 months)."),
      sc("pd-6", "When resuscitating a newborn who is not breathing and has HR < 100 bpm after drying & stimulation, what is the FIRST priority within the Golden Minute?", ["IV Epinephrine", "Positive-Pressure Ventilation (Bag-and-Mask) at 40–60 breaths/min with room air", "Chest compressions immediately without ventilation", "Gastric lavage"], 1, "Ventilating newborn lungs with bag-and-mask within 60 seconds is the #1 resuscitation action."),
      sc("pd-7", "At what age is the first Measles-Rubella (MR) vaccine routinely administered in Uganda?", ["At birth", "6 weeks", "9 months", "5 years"], 2, "MR is administered subcutaneously at 9 months (and booster at 18 months)."),
      sc("pd-8", "Which sign distinguishes Pneumonia from a simple cough/cold in a 10-month-old infant under IMCI?", ["Fast breathing (>= 50 breaths/min for age 2–11 months) or lower chest wall indrawing", "Fever 37.6°C alone", "Mild nasal congestion", "Appetite intact"], 0, "Respiratory rate cutoffs: < 2m >= 60/min; 2–11m >= 50/min; 1–5y >= 40/min."),
      sc("pd-9", "Which clinical sign defines Severe Malaria in a child rather than uncomplicated malaria?", ["Intermittent mild headache", "Prostration, convulsions, impaired consciousness, severe anemia (Hb < 5 g/dL), or hypoglycemia", "Mild nasal discharge", "Appetite normal"], 1, "Cerebral malaria / severe anemia / respiratory distress require parenteral IV Artesunate immediately."),
      sc("pd-10", "What is the correct chest compression to ventilation ratio when performing CPR on a neonate with HR < 60 bpm despite 30s effective PPV?", ["30:2", "15:2", "3:1 (90 compressions & 30 breaths per min)", "5:5"], 2, "Neonatal resuscitation uses a 3:1 compression-to-ventilation ratio."),
      sc("pd-11", "When assessing a sick infant aged 2 months to 5 years for Dehydration, which signs confirm SEVERE dehydration?", ["Alert, eager to drink", "Lethargic/unconscious, sunken eyes, unable to drink, skin pinch goes back VERY slowly (> 2 seconds)", "Normal skin turgor", "Tears present"], 1, "Two or more severe dehydration signs demand immediate Plan C IV Ringer's Lactate resuscitation."),
      sc("pd-12", "For a preterm low-birth-weight newborn in Uganda, Kangaroo Mother Care (KMC) primarily prevents:", ["Congenital heart disease", "Hypothermia, hypoglycemia, and neonatal sepsis while promoting weight gain", "Rh incompatibility", "Neonatal jaundice from ABO"], 1, "Skin-to-skin KMC stabilizes temperature, supports breastfeeding, and improves preterm survival."),
      sc("pd-13", "Which classic symptom characterizes Croup (Acute Laryngotracheobronchitis) in toddlers?", ["Inspiratory stridor and a harsh 'barking seal' cough worse at night", "Purulent ear discharge", "Cherry-red skin rash", "Painless watery diarrhea"], 0, "Subglottic edema in parainfluenza virus produces barking cough and stridor (treat with Dexamethasone)."),
      sc("pd-14", "What is the preferred first-line antibiotic for non-severe Pneumonia in Ugandan children aged 2–59 months?", ["Oral Chloramphenicol", "Oral Amoxicillin dispersible tablets (DT) for 5 days", "Vancomycin IV", "Ciprofloxacin"], 1, "Uganda MoH / WHO IMCI recommends high-dose oral Amoxicillin DT for outpatient pediatric pneumonia."),
      sc("pd-15", "Which finding on physical exam of a newborn should prompt suspicion of Congenital Heart Disease?", ["Acrocyanosis in first 2 hours only", "Central cyanosis (tongue/lips), tachypnea with sweating during feeds, and loud heart murmur", "Molding of cranial sutures", "Vernix caseosa on skin"], 1, "Central cyanosis and feeding fatigue point to congenital cardiac shunts or failure."),
      sc("pd-16", "Phototherapy is used to treat Neonatal Jaundice primarily to prevent bilirubin-induced encephalopathy known as:", ["Hydrocephalus", "Kernicterus", "Reye syndrome", "Necrotizing enterocolitis"], 1, "Unconjugated bilirubin crosses the infant blood-brain barrier and causes irreversible Kernicterus."),
      sc("pd-17", "In Severe Acute Malnutrition (SAM) during the initial stabilization phase (F-75), why must high-protein/high-iron feeds be avoided initially?", ["They cause weight gain too slowly", "Liver/renal organs cannot handle excess protein/sodium/iron yet (risks heart failure & refeeding shock)", "F-75 tastes bitter", "Iron increases height too fast"], 1, "Start with F-75 cautiously and wait to add Iron until the Rehabilitation (F-100 / RUTF) phase after infections clear."),
      sc("pd-18", "What does the Pentavalent vaccine protect Ugandan infants against?", ["Diphtheria, Pertussis, Tetanus, Hepatitis B, and Haemophilus influenzae type b (Hib)", "Measles, Mumps, Rubella, Polio, BCG", "Malaria, Typhoid, Cholera, Yellow Fever, Rabies", "HIV, Syphilis, HPV, Rotavirus, PCV"], 0, "DPT-HepB-Hib is given at 6, 10, and 14 weeks of age."),
      sc("pd-19", "Which intervention lowers neonatal umbilical cord infection risk in home or rural deliveries?", ["Applying cow dung or ash", "Chlorhexidine 7.1% gel / dry clean cord care", "Tightly wrapping the cord in plastic", "Soaking in unboiled river water"], 1, "Chlorhexidine cord care and clean dry care prevent deadly neonatal tetanus and omphalitis."),
      mc("pd-20", "Select ALL components of the IMCI Fever/Malaria Assessment in Uganda:", ["Perform Malaria RDT or blood smear microscopy", "Check for stiff neck or bulging fontanelle (meningitis)", "Inspect for measles rash, Koplik spots, or ear infection", "Give Aspirin to children under 12 with viral fever"], [0, 1, 2], "NEVER give Aspirin to children under 16 due to Reye syndrome risk; use Paracetamol."),
      mc("pd-21", "Select ALL vaccines administered at 6 weeks of age in Uganda (UNEPI):", ["Pentavalent 1 (IM left thigh)", "OPV 1 (Oral)", "PCV 1 (IM right thigh)", "Rotavirus 1 (Oral)"], [0, 1, 2, 3], "At 6 weeks: OPV1, Pentavalent1, PCV1, and Rota1."),
      mc("pd-22", "Select ALL clinical signs of Neonatal Hypoglycemia (< 2.5 mmol/L):", ["Jitteriness / tremors", "Weak high-pitched cry or lethargy", "Apnea or cyanotic spells", "Weight > 3.5 kg always guarantees immunity"], [0, 1, 2], "Both SGA and LGA infants of diabetic mothers are high risk for hypoglycemia."),
      mc("pd-23", "Select ALL correct rules for ORS preparation & administration at home:", ["Dissolve 1 standard sachet in 1 liter of clean boiled/cooled water", "Discard any unused ORS solution after 24 hours", "Give small frequent sips/spoons after every loose stool", "Boil the mixed ORS solution again after dissolving"], [0, 1, 2], "Never boil ORS after mixing; dissolve in clean cooled water and discard after 24h."),
      tf("pd-24", "Phototherapy requires covering the newborn's eyes with opaque eye shields and monitoring hydration status.", true, "True: eye shields protect the retina and phototherapy increases insensible water loss."),
      tf("pd-25", "Oral Rehydration Salts (ORS) works because sodium and glucose share a co-transporter (SGLT1) across the intestinal mucosa even during secretory diarrhea.", true, "True: coupled Na+/glucose transport pulls water osmotically into circulation."),
      tf("pd-26", "A child with bilateral pitting edema of both feet requires immediate treatment as Moderate Acute Malnutrition (Green MUAC).", false, "False: nutritional edema is ALWAYS classified as Severe Acute Malnutrition regardless of MUAC."),
      tf("pd-27", "Stridor in a resting, calm child is a dangerous sign of upper airway obstruction.", true, "True: stridor at rest requires urgent airway/steroid/nebulized adrenaline management.")
    ]
